import { intrinsicSizeMeasureFunc } from '../tools/utils.ts'
import Yoga from '@hanzo/layout';
import {
  Align,
  BoxSizing,
  Direction,
  Display,
  Edge,
  Errata,
  ExperimentalFeature,
  FlexDirection,
  GridTrackType,
  Gutter,
  Justify,
  MeasureMode,
  Overflow,
  PositionType,
  Unit,
  Wrap,
} from '@hanzo/layout';

test('grid_relative_all_sides', () => {
  const config = Yoga.Config.create();

  const root = Yoga.Node.create(config);
  root.setPositionType(PositionType.Absolute);
  root.setDisplay(Display.Grid);
  root.setHeight(100);
  root.setWidth(100);

  const root_child0 = Yoga.Node.create(config);
  root_child0.setWidth(40);
  root_child0.setPosition(Edge.Top, 10);
  root_child0.setPosition(Edge.Bottom, 10);
  root_child0.setPosition(Edge.Left, 10);
  root_child0.setPosition(Edge.Right, 10);
  root.insertChild(root_child0, 0);
  root.calculateLayout(undefined, undefined, Direction.LTR);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(100);
  expect(root.getComputedHeight()).toBe(100);

  expect(root_child0.getComputedLeft()).toBe(10);
  expect(root_child0.getComputedTop()).toBe(10);
  expect(root_child0.getComputedWidth()).toBe(40);
  expect(root_child0.getComputedHeight()).toBe(0);

  root.calculateLayout(undefined, undefined, Direction.RTL);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(100);
  expect(root.getComputedHeight()).toBe(100);

  expect(root_child0.getComputedLeft()).toBe(50);
  expect(root_child0.getComputedTop()).toBe(10);
  expect(root_child0.getComputedWidth()).toBe(40);
  expect(root_child0.getComputedHeight()).toBe(0);
});
